t:600}.log-entry time{color:#a6aca6;font:8px 'DM Mono',monospace;margin-right:7px}.shop-list{display:flex;flex-direction:column;gap:9px;margin-top:17px}.shop-item{padding:12px;border:1px solid #e6e4da;border-radius:4px;background:#f8f7f2;display:grid;grid-template-columns:38px 1fr auto;gap:10px;align-items:center}.shop-icon{height:36px;width:36px;border-radius:50%;display:grid;place-items:center;background:#ebeadd;font-size:20px}.shop-info strong{font-size:11px;display:block}.shop-info small{color:#89928b;font-size:9px;line-height:1.35;display:block;margin-top:3px}.buy-button{background:#294f44;color:#fff;border:0;border-radius:3px;padding:7px 9px;font:500 9px 'DM Mono',monospace;cursor:pointer;white-space:nowrap}.buy-button:hover:not(:disabled){background:#386b5a}.buy-button:disabled{background:#c9cec5;color:#f7f6f1;cursor:not-allowed}.buy-button span{color:#e8c877}.shop-tip{display:flex;gap:8px;margin-top:17px;color:#9a8c67;font-size:10px;line-height:1.5}.shop-tip:first-letter{font-size:18px}footer{display:flex;justify-content:space-between;padding:18px 0 20px;color:#9ba29a;font:8px 'DM Mono',monospace;letter-spacing:.4px}footer i{font-style:normal;color:#c9a158}.modal-backdrop{position:fixed;inset:0;background:#101b1be0;z-index:10;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(4px)}.battle-dialog{width:min(590px,100%);background:#faf9f3;border:1px solid #d5d4c4;border-radius:7px;padding:27px 31px 24px;box-shadow:0 25px 100px #0008;animation:rise .3s ease}@keyframes rise{from{transform:translateY(12px);opacity:0}to{transform:none;opacity:1}}.battle-topline{display:flex;justify-content:space-between;align-items:center}.battle-topline .eyebrow{color:#9a8050}.battle-turn{color:#557b62}.battle-dialog h2{font:700 29px 'Playfair Display',serif;margin:12px 0 3px}.battle-subtitle{margin:0;color:#87918a;font-size:12px}.combatants{display:grid;grid-template-columns:1fr 40px 1fr;align-items:center;margin:24px 0 12px}.combatant{background:#eff2e9;border:1px solid #dfe5d9;border-radius:5px;padding:13px;text-align:center}.enemy-combatant{background:#f3ece7;border-color:#e8ddd6}.combat-piece{font:56px 'DejaVu Sans',serif;color:#426458;line-height:1}.enemy-combatant .combat-piece{color:#815b4e}.combat-name{font:600 14px 'DM Sans',sans-serif;margin-top:3px}.combat-meta{font-size:9px;color:#8c958d;margin:3px 0 11px}.health-track,.mana-track{height:7px;background:#dce0d6;border-radius:5px;overflow:hidden}.health-fill{height:100%;background:#729a72;width:100%;transition:width .4s}.enemy-health{background:#c27d68}.mana-track{height:4px;margin-top:6px;background:#e2e1d8}.mana-fill{height:100%;background:#7892bc;width:100%;transition:width .4s}.enemy-mana{background:#9e87b1}.health-text,.mana-text{display:flex;justify-content:flex-end;color:#829087;font:8px 'DM Mono',monospace;margin-top:4px}.mana-text{font-size:7px;margin-top:3px}.versus{font:700 11px 'DM Mono',monospace;color:#b9a776;text-align:center}.battle-message{min-height:38px;margin:12px 0;padding:10px 13px;border-left:2px solid #c9a457;background:#f3f0e6;color:#67766b;font-size:11px;line-height:1.5}.battle-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.battle-action{padding:10px 8px;background:#234b40;border:1px solid #234b40;color:#fff;border-radius:3px;text-align:left;cursor:pointer}.battle-action:hover:not(:disabled){background:#326657}.battle-action:disabled{opacity:.42;cursor:not-allowed}.battle-action strong{font:600 10px 'DM Sans',sans-serif;display:block}.battle-action small{display:block;color:#b7c8bc;font-size:8px;margin-top:4px}.battle-action.special{background:#4b6170;border-color:#4b6170}.battle-action.item-action{background:#8c7041;border-color:#8c7041}.battle-result{padding:12px;text-align:center;background:#edf2e8;border:1px solid #d8e0d4;color:#42644f;border-radius:3px;font-weight:600;font-size:12px}.battle-result button{margin-left:12px;background:#294f44;color:white;border:0;border-radius:3px;padding:8px 15px;cursor:pointer;font:10px 'DM Sans',sans-serif}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,15px);opacity:0;pointer-events:none;background:#203d36;color:#fff;padding:11px 18px;border-radius:4px;font-size:11px;box-shadow:0 8px 25px #13241f55;transition:.25s;z-index:30}.toast.show{transform:translate(-50%,0);opacity:1}
