mbatant{padding:10px 7px}.combat-piece{font-size:44px}.combat-name{font-size:12px}.combat-meta{font-size:8px}.battle-actions{gap:5px}.battle-action{padding:9px 6px}.battle-action strong{font-size:9px}.battle-action small{font-size:7px}}@media(max-width:370px){.intro h1{font-size:23px}.intro p{max-width:200px}.turn-pill{flex-direction:column;align-items:flex-start}.turn-pill b{border-left:0;padding:0;margin:0}.shop-list{grid-template-columns:1fr}.player-card{gap:5px}.board-tools{gap:7px}}

const TYPES={K:{name:'Rey',glyph:'♔',black:'♚',hp:42,mp:18,atk:7,ability:'Mandato real',skill:'Ordena a su guardia y recupera 8 PV.',cost:5},Q:{name:'Reina',glyph:'♕',black:'♛',hp:34,mp:26,atk:10,ability:'Lanza astral',skill:'Golpe mágico devastador.',cost:9},R:{name:'Torre',glyph:'♖',black:'♜',hp:38,mp:18,atk:8,ability:'Bastión',skill:'Se protege y restaura 10 PV.',cost:5},B:{name:'Alfil',glyph:'♗',black:'♝',hp:28,mp:26,atk:7,ability:'Luz sanadora',skill:'Recupera 12 PV y 3 de éter.',cost:4},N:{name:'Caballo',glyph:'♘',black:'♞',hp:31,mp:20,atk:9,ability:'Estocada',skill:'Ataque rápido con probabilidad de crítico.',cost:4},P:{name:'Peón',glyph:'♙',black:'♟',hp:22,mp:14,atk:5,ability:'Espíritu tenaz',skill:'Golpea con fuerza creciente.',cost:2}};
const SHOP=[{id:'potion',name:'Poción',icon:'⚗',price:35,desc:'Restaura 18 PV a una pieza.'},{id:'ether',name:'Éter',icon:'✧',price:30,desc:'Restaura 12 puntos de esencia.'},{id:'revive',name:'Revivir',icon:'✦',price:70,desc:'Devuelve a una pieza caída con la mitad de sus PV.'}];
const STORE='reinos-eter-v1';let state,selected=null,legal=[],flipped=false,battle=null,toastTimer,aiTimer;
function makePiece(type,color,x,y,n){const t=TYPES[type];return{id:`${color}-${type}-${n}`,type,color,x,y,hp:t.hp,maxHp:t.hp,mp:t.mp,maxMp:t.mp,level:1,xp:0,alive:true,moved:false}}
function freshState(){const pieces=[];let n=0;for(let x=0;x<8;x++){pieces.push(makePiece('P','b',x,1,n++),makePiece('P','w',x,6,n++))}const back=['R','N','B','Q','K','B','N','R'];back.forEach((t,x)=>{pieces.push(makePiece(t,'b',x,0,n++),makePiece(t,'w',x,7,n++))});return{pieces,turn:'w',move:1,gold:120,inventory:{potion:2,ether:1,revive:1},selected:null,lastMove:null,log:[],gameOver:false,winner:null}}
function load(){try{const d=JSON.parse(localStorage.getItem(STORE));if(d&&Array.isArray(d.pieces))return d}catch(e){}return freshState()}
state=load();
const $=id=>document.getElementById(id);const boardEl=$('board');
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));$('saveStatus')?.classList.add('saved')}catch(e){}}
function pieceAt(x,y){return state.pieces.find(p=>p.alive&&p.x===x&&p.y===y)}function own(p){return p&&p.color==='w'}function label(p){return TYPES[p.type].name}
function addLog(text){state.log.unshift({text,time:new Date().toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit'})});state.log=state.log.slice(0,20);renderLog();save()}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function inBounds(x,y){return x>=0&&x<8&&y>=0&&y<8}
function pseudo(p){const out=[],{x,y,type,color}=p,dir=color==='w'?-1:1;const add=(a,b)=>{if(!inBounds(a,b))return false;const q=pieceAt(a,b);if(!q)out.push([a,b]);else if(q.color!==color)out.push([a,b]);return !q};if(type==='P'){if(inBounds(x,y+dir)&&!pieceAt(x,y+dir)){out.push([x,y+dir]);if(!p.moved&&!pieceAt(x,y+2*dir))out.push([x,y+2*dir])}for(const dx of [-1,1]){const q=pieceAt(x+dx,y+dir);if(q&&q.color!==color)out.push([x+dx,y+dir])}}else if(type==='N){for(const [dx,dy] of [[1,2],[2,1],[2,-1],[1,-2],[-1,-2],[-2,-1],[-2,1],[-1,2]]){const q=pieceAt(x+dx,y+dy);if(inBounds(x+dx,y+dy)&&(!q||q.color!==color))out.push([x+dx,y+dy])}}else if(type==='K'){for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)if((dx||dy)){const q=pieceAt(x+dx,y+dy);if(inBounds(x+dx,y+dy)&&(!q||q.color!==color))out.push([x+dx,y+dy])}}else{const dirs=[];if(type==='R'||type==='Q')dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(type==='B'||type==='Q')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dx,dy]of dirs){let a=x+dx,b=y+dy;while(add(a,b)){a+=dx;b+=dy}}}return out}
function isAttacked(x,y,by){return state.pieces.some(p=>p.alive&&p.color===by&&pseudo(p).some(([a,b])=>a===x&&b===y))}
function king(color){return state.pieces.find(p=>p.alive&&p.color===color&&p.type==='K')}
function inCheck(color){const k=king(color);return k?isAttacked(k.x,k.y,color==='w'?'b':'w'):true}
function legalMoves(p){return pseudo(p).filter(([x,y])=>{const target=pieceAt(x,y),ox=p.x,oy=p.y;p.x=x;p.y=y;if(target)target.alive=false;const safe=!inCheck(p.color);p.x=ox;p.y=oy;if(target)target.alive=true;return safe})}
function allMoves(color){return state.pieces.filter(p=>p.alive&&p.color===color).flatMap(p=>legalMoves(p).map(([x,y])=>({p,x,y,capture:!!pieceAt(x,y)})))}
function renderBoard(){boardEl.innerHTML='';const ranks=flipped?[...Array(8).keys()]:[...Array(8).keys()].reverse(),files=flipped?[...Array(8).keys()].reverse():[...Array(8).keys()];for(const y of ranks)for(const x of files){const sq=document.createElement('div');sq.className=`square ${(x+y)%2?'dark':'light'}`;sq.setAttribute('role','gridcell');sq.dataset.x=x;sq.dataset.y=y;const p=pieceAt(x,y);if(state.lastMove&&((state.lastMove.from[0]===x&&state.lastMove.from[1]===y)||(state.lastMove.to[0]===x&&state.lastMove.to[1]===y)))sq.classList.add('last-move');if(p&&p.type==='K'&&inCheck(p.color))sq.classList.add('check');if(selected===p)sq.classList.add('selected');if(legal.some(m=>m[0]===x&&m[1]===y))sq.classList.add('legal',p?'capture':'');if(p){const span=document.createElement('span');span.className=`piece ${p.color==='w'?'white':'black'}`;span.textContent=p.color==='w'?TYPES[p.type].glyph:TYPES[p.type].black;sq.append(span);if(own(p)&&p.level>1){const lev=document.createElement('span');lev.className='piece-level';lev.textContent=`${p.level}`;sq.append(lev)}}sq.addEventListener('click',()=>onSquare(x,y));boardEl.append(sq)}$('rankLabels').innerHTML=(flipped?'12345678':'87654321').split('').map(v=>`<span>${v}</span>`).join('');$('fileLabels').innerHTML=(flipped?'hgfedcba':'abcdefgh').split('').map(v=>`<span>${v}</span>`).join('')}
function onSquare(x,y){if(battle||state.gameOver||state.turn!=='w')return;const p=pieceAt(x,y);if(selected&&legal.some(m=>m[0]===x&&m[1]===y)){const mover=selected,target=pieceAt(x,y);selected=null;legal=[];if(target)startBattle(mover,target,x,y);else applyMove(mover,x,y);return}if(p&&p.color==='w'){selected=p;legal=legalMoves(p)}else{selected=null;legal=[]}renderBoard()}
function applyMove(p,x,y){const from=[p.x,p.y];p.x=x;p.y=y;p.moved=true;if(p.type==='P'&&(y===0||y===7)){p.type='Q';p.maxHp=TYPES.Q.hp+5*(p.level-1);p.hp=Math.min(p.maxHp,p.hp+8);p.maxMp=TYPES.Q.mp+4*(p.level-1);toast('¡Tu peón ha ascendido a Reina!');addLog(`<strong>${label(p)}</strong> asciende por el tablero.`)}state.lastMove={from,to:[x,y]};endTurn(p.color);renderAll()}
function endTurn(movedColor){state.turn=movedColor==='w'?'b':'w';if(movedColor==='b')state.move++;selected=null;legal=[];const moves=allMoves(state.turn);if(!moves.length){state.gameOver=true;state.winner=inCheck(state.turn)?movedColor:null;addLog(state.winner?`<strong>${state.winner==='w'?'Guardia del Alba':'La Sombra'}</strong> gana la partida por jaque mate.`:'La partida termina en tablas.');toast(state.winner?(state.winner==='w'?'¡Jaque mate! Has ganado':'Jaque mate. La Sombra gana'):'Tablas.');}else if(inCheck(state.turn))addLog(`<strong>¡Jaque!</strong> El rey ${state.turn==='w'?'del Alba':'de la Sombra'} está amenazado.`);save();renderBoard();renderHud();if(state.turn==='b'&&!state.gameOver&&!battle)aiTimer=setTimeout(aiMove,650)}
function startBattle(attacker,defender,x,y){battle={attacker,defender,to:[x,y],turn:attacker.color,round:1};$('battleModal').classList.remove('hidden');$('battleTitle').textContent=`${label(attacker)} vs ${label(defender)}`;$('battleSubtitle').textContent=`¡La captura desata un duelo de esencias!`;updateBattle();addLog(`<strong>${label(attacker)}</strong> desafía a ${label(defender)} en un duelo.`);if(battle.turn==='b')scheduleAI()}
function updateBattle(message){if(!battle)return;const a=battle.attacker,d=battle.defender;const set=(id,v)=>$(id).textContent=v;set('attackerGlyph',a.color==='w'?TYPES[a.type].glyph:TYPES[a.type].black);set('defenderGlyph',d.color==='w'?TYPES[d.type].glyph:TYPES[d.type].black);set('attackerName',label(a));set('defenderName',label(d));set('attackerMeta',`Nv. ${a.level} · ${a.color==='w'?'Guardia del Alba':'La Sombra'}`);set('defenderMeta',`Nv. ${d.level} · ${d.color==='w'?'Guardia del Alba':'La Sombra'}`);$('attackerHpBar').style.width=`${Math.max(0,a.hp/a.maxHp*100)}%`;$('defenderHpBar').style.width=`${Math.max(0,d.hp/d.maxHp*100)}%`;$('attackerMpBar').style.width=`${a.mp/a.maxMp*100}%`;$('defenderMpBar').style.width=`${d.mp/d.maxMp*100}%`;set('attackerHpText',`${Math.max(0,a.hp)} / ${a.maxHp} PV`);set('defenderHpText',`${Math.max(0,d.hp)} / ${d.maxHp} PV`);set('attackerMpText',`${a.mp} / ${a.maxMp} ÉTER`);set('defenderMpText',`${d.mp} / ${d.maxMp} ÉTER`);set('battleTurn',battle.turn==='w'?'TU ACCIÓN':'ACCIÓN DEL RIVAL');$('battleMessage').textContent=message||`Ronda ${battle.round}. ${battle.turn==='w'?'Elige la acción de tu pieza.':'La Sombra prepara su movimiento...'}`;renderBattleActions();save()}
function renderBattleActions(){const host=$('battleActions');host.innerHTML='';$('battleResult').classList.add('hidden');if(battle.turn!=='w'){host.innerHTML='<div class="battle-message">La Sombra está pensando...</div>';return}const p=battle.attacker.color==='w'?battle.attacker:battle.defender;const add=(title,desc,cls,disabled,fn)=>{const b=document.createElement('button');b.className=`battle-action ${cls||''}`;b.disabled=!!disabled;b.innerHTML=`<strong>${title}</strong><small>${desc}</small>`;b.onclick=fn;host.append(b)};add('Ataque básico',`Daño ${attackPower(p)} · sin coste`,'',false,()=>playerAction('attack'));add(TYPES[p.type].ability,`${TYPES[p.type].skill} · ${abilityCost(p)} éter`,'special',p.mp<abilityCost(p),()=>playerAction('skill'));const has=state.inventory.potion>0;add(`⚗ Poción (${state.inventory.potion})`,'Restaura 14 PV en combate','item-action',!has||p.hp>=p.maxHp,()=>playerAction('potion'));const ether=state.inventory.ether>0;add(`✧ Éter (${state.inventory.ether})`,'Restaura 10 de esencia','item-action',!ether||p.mp>=p.maxMp,()=>playerAction('ether'))}
function attackPower(p){return TYPES[p.type].atk+2*(p.level-1)}function abilityCost(p){return p.type==='K'?5:p.type==='R'?5:p.type==='B'?6:7}
function playerAction(action){if(!battle||battle.turn!=='w')return;combatAction(action);if(battle)setTimeout(()=>{if(battle&&battle.turn==='b')scheduleAI()},450)}
function combatAction(action,ai=false){const a=battle.attacker,d=battle.defender,p=battle.turn==='w'? (a.color==='w'?a:d):(a.color==='b'?a:d),target=p===a?d:a;let message='';if(action==='attack'){let damage=attackPower(p)+Math.floor(Math.random()*4);if(Math.random()<.12){damage=Math.round(damage*1.6);message=`¡Golpe crítico! ${label(p)} causa ${damage} de daño.`}else message=`${label(p)} ataca y causa ${damage} de daño.`;target.hp-=damage}else if(action==='skill'){const cost=abilityCost(p);if(p.mp<cost)return;p.mp-=cost;if(p.type==='K'){p.hp=Math.min(p.maxHp,p.hp+8);target.hp-=attackPower(p)+2;message='Mandato real: la guardia protege al rey y golpea al rival.'}else if(p.type==='R'){p.hp=Math.min(p.maxHp,p.hp+10);p.mp=Math.min(p.maxMp,p.mp+2);message='Bastión: la torre se fortifica y recupera 10 PV.'}else if(p.type==='B'){p.hp=Math.min(p.maxHp,p.hp+12);p.mp=Math.min(p.maxMp,p.mp+3);message='Luz sanadora: el alfil recupera 12 PV.'}else{let damage=attackPower(p)+(p.type==='Q'?9:p.type==='N'?5:p.type==='P'?4:6)+Math.floor(Math.random()*4);if(p.type==='N'&&Math.random()<.35)damage+=8;target.hp-=damage;message=`${TYPES[p.type].ability}: ${label(p)} causa ${damage} de daño.`}}else if(action==='potion'){state.inventory.potion--;p.hp=Math.min(p.maxHp,p.hp+14);message=`Una poción restaura 14 PV a ${label(p)}.`}else if(action==='ether'){state.inventory.ether--;p.mp=Math.min(p.maxMp,p.mp+10);message=`Un éter restaura 10 puntos de esencia.`}target.hp=Math.max(0,target.hp);battle.round++;if(target.hp<=0){finishBattle(p,target);return}battle.turn=battle.turn==='w'?'b':'w';updateBattle(message);renderAll()}
function scheduleAI(){if(!battle)return;clearTimeout(aiTimer);aiTimer=setTimeout(()=>{if(!battle||battle.turn!=='b')return;const p=battle.attacker.color==='b'?battle.attacker:battle.defender;let action='attack';if(p.hp<p.maxHp*.42&&p.mp>=abilityCost(p)&&['R','B','K'].includes(p.type))action='skill';else if(p.mp>=abilityCost(p)&&Math.random()<.48)action='skill';combatAction(action,true);if(battle&&battle.turn==='b')scheduleAI()},900)}
function finishBattle(winner,loser){const {attacker,defender,to}=battle;loser.alive=false;loser.hp=0;if(winner===attacker){attacker.x=to[0];attacker.y=to[1];attacker.moved=true}winner.xp+=winner.color==='w'?35:20;let leveled=false;while(winner.xp>=winner.level*50){winner.xp-=winner.level*50;winner.level++;winner.maxHp+=winner.type==='P'?4:6;winner.maxMp+=4;winner.hp=Math.min(winner.maxHp,winner.hp+8);winner.mp=Math.min(winner.maxMp,winner.mp+4);leveled=true}const playerWon=winner.color==='w';if(playerWon){const reward=18+winner.level*3;state.gold+=reward;state.inventory.potion++;addLog(`<strong>¡Victoria!</strong> ${label(winner)} vence y consigues ${reward} ✦ y una poción.`);$('battleResult').innerHTML=`¡Victoria! +${reward} ✦ · +1 Poción ${leveled?'· ¡Subió a nivel '+winner.level+'!':''} <button id="continueBattle">Continuar</button>`}else{addLog(`<strong>Derrota.</strong> ${label(loser)} cae en el duelo.`);$('battleResult').innerHTML=`La Sombra vence este duelo. ${leveled?'¡Su pieza subió al nivel '+winner.level+'!':''} <button id="continueBattle">Continuar</button>`}if(leveled)addLog(`<strong>${label(winner)}</strong> alcanza el nivel ${winner.level}.`);$('battleActions').innerHTML='';$('battleMessage').textContent=`${label(winner)} derrota a ${label(loser)}.`;$('battleResult').classList.remove('hidden');$('continueBattle').onclick=()=>{battle=null;$('battleModal').classList.add('hidden');state.lastMove={from:[attacker.x,attacker.y],to:[winner.x,winner.y]};endTurn(attacker.color);renderAll()};renderAll();save()}

let rosterSelected=null;
function renderHud(){const white=state.pieces.filter(p=>p.alive&&p.color==='w'),black=state.pieces.filter(p=>p.alive&&p.color==='b');$('playerArmy').textContent=`${white.length} piezas en combate`;$('enemyArmy').textContent=`${black.length} piezas en combate`;$('armyTabCount').textContent=white.length;$('unitCount').textContent=`${white.length} / 16`;$('goldCount').textContent=state.gold;$('shopGold').textContent=state.gold;$('moveCount').textContent=`MOV. ${String(state.move).padStart(2,'0')}`;$('turnText').textContent=state.gameOver?(state.winner==='w'?'VICTORIA':'PARTIDA FINALIZADA'):state.turn==='w'?'TU TURNO':'TURNO RIVAL';$('turnPill').classList.toggle('enemy-turn',state.turn==='b');$('turnHint').textContent=state.gameOver?(state.winner==='w'?'¡Has conquistado el reino!':'La partida ha terminado'):state.turn==='w'?'Selecciona una pieza para moverla':'La Sombra está pensando...';const avg=white.length?Math.round(white.reduce((n,p)=>n+p.level,0)/white.length):1;$('armyLevel').textContent=`NV. ${avg}`;$('undoMove').disabled=!state.undoSnapshot||state.turn!=='w'||!!battle;$('undoMove').style.opacity=$('undoMove').disabled?'.45':'1'}
function renderRoster(){const list=$('unitList');list.innerHTML='';const units=state.pieces.filter(p=>p.color==='w').sort((a,b)=>a.alive===b.alive?(a.type===b.type?b.level-a.level:'KQRBNP'.indexOf(a.type)-'KQRBNP'.indexOf(b.type)):a.alive?-1:1);for(const p of units){const row=document.createElement('div');row.className=`unit-row ${rosterSelected===p.id?'selected':''}`;const hp=Math.max(0,p.hp)/p.maxHp*100;row.innerHTML=`<div class="unit-icon" style="opacity:${p.alive?1:.35}">${TYPES[p.type].glyph}</div><div class="unit-copy"><div class="unit-name">${label(p)} ${!p.alive?'<small>CAÍDO</small>':''}<small>NV. ${p.level}</small></div><div class="unit-stats"><span>${p.alive?Math.max(0,p.hp):0}/${p.maxHp} PV</span><span>${p.mp}/${p.maxMp} ÉTER</span></div></div><div class="unit-health"><span class="${hp<30?'low':''}" style="width:${p.alive?hp:0}%"></span></div>`;row.onclick=()=>{rosterSelected=p.id;renderRoster();renderDetail()};list.append(row)}renderDetail()}
function renderDetail(){const host=$('unitDetail'),p=state.pieces.find(v=>v.id===rosterSelected&&v.color==='w');if(!p){host.innerHTML='<div class="detail-empty">Selecciona un campeón para ver sus objetos y progreso.</div>';return}const xpNeed=p.level*50;host.innerHTML=`<div class="detail-head"><span class="detail-symbol">${TYPES[p.type].glyph}</span><div class="detail-title"><strong>${label(p)} · Nivel ${p.level}</strong><small>${TYPES[p.type].ability} · ${p.alive?'En formación':'Caído'}</small></div></div><div class="xp-bar"><span style="width:${p.xp/xpNeed*100}%"></span></div><div class="detail-actions"><button class="item-use" data-use="potion" ${!p.alive||p.hp>=p.maxHp||state.inventory.potion<1?'disabled':''}>⚗ Poción ×${state.inventory.potion}</button><button class="item-use" data-use="ether" ${!p.alive||p.mp>=p.maxMp||state.inventory.ether<1?'disabled':''}>✧ Éter ×${state.inventory.ether}</button><button class="item-use" data-use="revive" ${p.alive||state.inventory.revive<1?'disabled':''}>✦ Revivir ×${state.inventory.revive}</button></div>`;host.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useItem(b.dataset.use,p))}
function renderShop(){const list=$('shopList');list.innerHTML='';for(const item of SHOP){const count=state.inventory[item.id]||0;const card=document.createElement('div');card.className='shop-item';card.innerHTML=`<div class="shop-icon">${item.icon}</div><div class="shop-info"><strong>${item.name} <span style="font:8px 'DM Mono';color:#9ba39a">×${count}</span></strong><small>${item.desc}</small></div><button class="buy-button" ${state.gold<item.price?'disabled':''}>✦ <span>${item.price}</span></button>`;card.querySelector('button').onclick=()=>buyItem(item);list.append(card)}}
function buyItem(item){if(state.gold<item.price){toast('No tienes suficiente oro.');return}state.gold-=item.price;state.inventory[item.id]=(state.inventory[item.id]||0)+1;addLog(`Compraste <strong>${item.name}</strong> en el bazar.`);toast(`${item.name} añadido a tu bolsa.`);renderAll()}
function useItem(item,p){if(!p)return;if(item==='revive'){if(p.alive||!state.inventory.revive)return;state.inventory.revive--;p.alive=true;p.hp=Math.ceil(p.maxHp/2);p.mp=Math.ceil(p.maxMp/2);if(p.x<0||p.y<0){const slot=findEmptyHome();if(!slot){p.alive=false;state.inventory.revive++;toast('No hay espacio libre en tu fila de inicio.');return}p.x=slot[0];p.y=slot[1]}addLog(`<strong>${label(p)}</strong> vuelve a la batalla gracias a Revivir.`);toast(`${label(p)} ha revivido.`)}else if(item==='potion'){if(!state.inventory.potion||!p.alive||p.hp>=p.maxHp)return;state.inventory.potion--;p.hp=Math.min(p.maxHp,p.hp+18);addLog(`Una <strong>Poción</strong> restaura PV a ${label(p)}.`);toast('Poción utilizada.')}else if(item==='ether'){if(!state.inventory.ether||!p.alive||p.mp>=p.maxMp)return;state.inventory.ether--;p.mp=Math.min(p.maxMp,p.mp+12);addLog(`Un <strong>Éter</strong> restaura esencia a ${label(p)}.`);toast('Éter utilizado.')}save();renderAll()}
function findEmptyHome(){for(let x=0;x<8;x++)if(!pieceAt(x,7))return[x,7];return null}
function renderLog(){$('logEntries').innerHTML=state.log.map(e=>`<div class="log-entry"><time>${e.time}</time>${e.text}</div>`).join('')||'<div class="log-entry">La crónica aguarda su primer duelo...</div>'}
function renderAll(){renderBoard();renderHud();renderRoster();renderShop();renderLog()}
function aiMove(){if(state.turn!=='b'||state.gameOver||battle)return;const moves=allMoves('b');if(!moves.length)return;const captures=moves.filter(m=>m.capture);let choice;if(captures.length&&Math.random()<.66){captures.sort((a,b)=>TYPES[a.piece?.type||a.p.type]?.cost-TYPES[b.p.type]?.cost);choice=captures[Math.floor(Math.random()*Math.min(3,captures.length))]}else choice=moves[Math.floor(Math.random()*moves.length)];const target=pieceAt(choice.x,choice.y);if(target){startBattle(choice.p,target,choice.x,choice.y)}else{applyMove(choice.p,choice.x,choice.y);addLog(`<strong>La Sombra</strong> mueve ${label(choice.p)}.`)}}
function selectTab(tab){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('armyPanel').classList.toggle('hidden',tab!=='army');$('shopPanel').classList.toggle('hidden',tab!=='shop')}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>selectTab(b.dataset.tab)));
$('flipBoard').onclick=()=>{flipped=!flipped;renderBoard()};$('resetGame').onclick=()=>{if(confirm('¿Empezar una nueva partida? Se perderá el progreso guardado.')){clearTimeout(aiTimer);state=freshState();selected=null;legal=[];battle=null;rosterSelected=null;$('battleModal').classList.add('hidden');save();renderAll();toast('Nuevo reino listo para la batalla.')}};
$('undoMove').onclick=()=>{if(!state.undoSnapshot||state.turn!=='w'||battle)return;try{const prior=JSON.parse(state.undoSnapshot);state=prior;state.undoSnapshot=null;selected=null;legal=[];clearTimeout(aiTimer);save();renderAll();toast('Movimiento deshecho.')}catch(e){toast('No se pudo deshacer el movimiento.')}};
$('clearLog').onclick=()=>{state.log=[];renderLog();save()};$('soundToggle').onclick=e=>{e.currentTarget.classList.toggle('muted');toast(e.currentTarget.classList.contains('muted')?'Sonido desactivado':'Sonido activado')};
// Guardamos el estado anterior al inicio de cada jugada humana para permitir deshacer el turno completo.
const originalSquare=onSquare;
onSquare=function(x,y){if(selected&&legal.some(m=>m[0]===x&&m[1]===y)&&state.turn==='w'&&!battle)state.undoSnapshot=JSON.stringify({...state,undoSnapshot:null});originalSquare(x,y)};
// Resucitar en la fila inicial conserva la estructura del tablero y no desplaza otras piezas.
function repairFallenPositions(){for(const p of state.pieces.filter(p=>p.color==='w'&&!p.alive)){p.x=-1;p.y=-1}}
renderAll();if(state.turn==='b'&&!state.gameOver)setTimeout(aiMove,700);

