if(state.turn==='b'&&!state.gameOver&&!battle)aiTimer=setTimeout(aiMove,650)}
function startBattle(attacker,defender,x,y){battle={attacker,defender,to:[x,y],turn:attacker.color,round:1};$('battleModal').classList.remove('hidden');$('battleTitle').textContent=`${label(attacker)} vs ${label(defender)}`;$('battleSubtitle').textContent='¡La captura desata un duelo de esencias!';updateBattle();addLog(`<strong>${label(attacker)}</strong> desafía a ${label(defender)} en un duelo.`);if(battle.turn==='b')scheduleAI()}
function updateBattle(message){if(!battle)return;const a=battle.attacker,d=battle.defender,set=(id,v)=>$(id).textContent=v;set('attackerGlyph',a.color==='w'?TYPES[a.type].glyph:TYPES[a.type].black);set('defenderGlyph',d.color==='w'?TYPES[d.type].glyph:TYPES[d.type].black);set('attackerName',label(a));set('defenderName',label(d));set('attackerMeta',`Nv. ${a.level} · ${a.color==='w'?'Guardia del Alba':'La Sombra'}`);set('defenderMeta',`Nv. ${d.level} · ${d.color==='w'?'Guardia del Alba':'La Sombra'}`);$('attackerHpBar').style.width=`${Math.max(0,a.hp/a.maxHp*100)}%`;$('defenderHpBar').style.width=`${Math.max(0,d.hp/d.maxHp*100)}%`;$('attackerMpBar').style.width=`${a.mp/a.maxMp*100}%`;$('defenderMpBar').style.width=`${d.mp/d.maxMp*100}%`;set('attackerHpText',`${Math.max(0,a.hp)} / ${a.maxHp} PV`);set('defenderHpText',`${Math.max(0,d.hp)} / ${d.maxHp} PV`);set('attackerMpText',`${a.mp} / ${a.maxMp} ÉTER`);set('defenderMpText',`${d.mp} / ${d.maxMp} ÉTER`);set('battleTurn',battle.turn==='w'?'TU ACCIÓN':'ACCIÓN DEL RIVAL');$('battleMessage').textContent=message||`Ronda ${battle.round}. ${battle.turn==='w'?'Elige la acción de tu pieza.':'La Sombra prepara su movimiento...'}`;renderBattleActions();save()}
function attackPower(p){return TYPES[p.type].atk+2*(p.level-1)}function abilityCost(p){return p.type==='K'?5:p.type==='R'?5:p.type==='B'?6:7}
function renderBattleActions(){const host=$('battleActions');host.innerHTML='';$('battleResult').classList.add('hidden');if(battle.turn!=='w'){host.innerHTML='<div class="battle-message">La Sombra está pensando...</div>';return}const p=battle.attacker.color==='w'?battle.attacker:battle.defender;const add=(title,desc,cls,disabled,fn)=>{const b=document.createElement('button');b.className=`battle-action ${cls||''}`;b.disabled=!!disabled;b.innerHTML=`<strong>${title}</strong><small>${desc}</small>`;b.onclick=fn;host.append(b)};add('Ataque básico',`Daño ${attackPower(p)} · sin coste`,'',false,()=>playerAction('attack'));add(TYPES[p.type].ability,`${TYPES[p.type].skill} · ${abilityCost(p)} éter`,'special',p.mp<abilityCost(p),()=>playerAction('skill'));add(`⚗ Poción (${state.inventory.potion})`,'Restaura 14 PV en combate','item-action',!state.inventory.potion||p.hp>=p.maxHp,()=>playerAction('potion'));add(`✧ Éter (${state.inventory.ether})`,'Restaura 10 de esencia','item-action',!state.inventory.ether||p.mp>=p.maxMp,()=>playerAction('ether'))}
function playerAction(action){if(!battle||battle.turn!=='w')return;combatAction(action);if(battle&&battle.turn==='b')setTimeout(()=>{if(battle&&battle.turn==='b')scheduleAI()},450)}
function combatAction(action){const a=battle.attacker,d=battle.defender,p=battle.turn==='w'?(a.color==='w'?a:d):(a.color==='b'?a:d),target=p===a?d:a;let message='';if(action==='attack'){let damage=attackPower(p)+Math.floor(Math.random()*4);if(Math.random()<.12){damage=Math.round(damage*1.6);message=`¡Golpe crítico! ${label(p)} causa ${damage} de daño.`}else message=`${label(p)} ataca y causa ${damage} de daño.`;target.hp-=damage}else if(action==='skill'){if(p.mp<abilityCost(p))return;p.mp-=abilityCost(p);if(p.type==='K'){p.hp=Math.min(p.maxHp,p.hp+8);target.hp-=attackPower(p)+2;message='Mandato real: el rey se cura y golpea al rival.'}else if(p.type==='R'){p.hp=Math.min(p.maxHp,p.hp+10);p.mp=Math.min(p.maxMp,p.mp+2);message='Bastión: la torre se fortifica y recupera 10 PV.'}else if(p.type==='B'){p.hp=Math.min(p.maxHp,p.hp+12);p.mp=Math.min(p.maxMp,p.mp+3);message='Luz sanadora: el alfil recupera 12 PV.'}else{let damage=attackPower(p)+(p.type==='Q'?9:p.type==='N'?5:p.type==='P'?4:6)+Math.floor(Math.random()*4);if(p.type==='N'&&Math.random()<.35)damage+=8;target.hp-=damage;message=`${TYPES[p.type].ability}: ${label(p)} causa ${damage} de daño.`}}else if(action==='potion'){state.inventory.potion--;p.hp=Math.min(p.maxHp,p.hp+14);message=`Una poción restaura 14 PV a ${label(p)}.`}else if(action==='ether'){state.inventory.ether--;p.mp=Math.min(p.maxMp,p.mp+10);message='Un éter restaura 10 puntos de esencia.'}target.hp=Math.max(0,target.hp);battle.round++;if(target.hp<=0){finishBattle(p,target);return}battle.turn=battle.turn==='w'?'b':'w';updateBattle(message);renderAll()}
function scheduleAI(){if(!battle)return;clearTimeout(aiTimer);aiTimer=setTimeout(()=>{if(!battle||battle.turn!=='b')return;const p=battle.attacker.color==='b'?battle.attacker:battle.defender;let action='attack';if(p.hp<p.maxHp*.42&&p.mp>=abilityCost(p)&&['R','B','K'].includes(p.type))action='skill';else if(p.mp>=abilityCost(p)&&Math.random()<.48)action='skill';combatAction(action);if(battle&&battle.turn==='b')scheduleAI()},900)}
function finishBattle(winner,loser){const{attacker,defender,to}=battle;loser.alive=false;loser.hp=0;if(winner===attacker){attacker.x=to[0];attacker.y=to[1];attacker.moved=true}winner.xp+=winner.color==='w'?35:20;let leveled=false;while(winner.xp>=winner.level*50){winner.xp-=winner.level*50;winner.level++;winner.maxHp+=winner.type==='P'?4:6;winner.maxMp+=4;winner.hp=Math.min(winner.maxHp,winner.hp+8);winner.mp=Math.min(winner.maxMp,winner.mp+4);leveled=true}const reward=18+winner.level*3;if(winner.color==='w'){state.gold+=reward;state.inventory.potion++;addLog(`<strong>¡Victoria!</strong> ${label(winner)} vence y consigues ${reward} ✦ y una poción.`);$('battleResult').innerHTML=`¡Victoria! +${reward} ✦ · +1 Poción ${leveled?'· ¡Subió a nivel '+winner.level+'!':''} <button id="continueBattle">Continuar</button>`}else{addLog(`<strong>Derrota.</strong> ${label(loser)} cae en el duelo.`);$('battleResult').innerHTML=`La Sombra vence este duelo. ${leveled?'¡Su pieza subió al nivel '+winner.level+'!':''} <button id="continueBattle">Continuar</button>`}if(leveled)addLog(`<strong>${label(winner)}</strong> alcanza el nivel ${winner.level}.`);$('battleActions').innerHTML='';$('battleMessage').textContent=`${label(winner)} derrota a ${label(loser)}.`;$('battleResult').classList.remove('hidden');$('continueBattle').onclick=()=>{battle=null;$('battleModal').classList.add('hidden');state.lastMove={from:[attacker.x,attacker.y],to:[winner.x,winner.y]};endTurn(attacker.color);renderAll()};renderAll();save()}

