function renderHud(){const white=state.pieces.filter(p=>p.alive&&p.color==='w'),black=state.pieces.filter(p=>p.alive&&p.color==='b');$('playerArmy').textContent=`${white.length} piezas en combate`;$('enemyArmy').textContent=`${black.length} piezas en combate`;$('armyTabCount').textContent=white.length;$('unitCount').textContent=`${white.length} / 16`;$('goldCount').textContent=state.gold;$('shopGold').textContent=state.gold;$('moveCount').textContent=`MOV. ${String(state.move).padStart(2,'0')}`;$('turnText').textContent=state.gameOver?(state.winner==='w'?'VICTORIA':'PARTIDA FINALIZADA'):state.turn==='w'?'TU TURNO':'TURNO RIVAL';$('turnPill').classList.toggle('enemy-turn',state.turn==='b');$('turnHint').textContent=state.gameOver?(state.winner==='w'?'¡Has conquistado el reino!':'La partida ha terminado'):state.turn==='w'?'Selecciona una pieza para moverla':'La Sombra está pensando...';const avg=white.length?Math.round(white.reduce((n,p)=>n+p.level,0)/white.length):1;$('armyLevel').textContent=`NV. ${avg}`;$('undoMove').disabled=!state.undoSnapshot||state.turn!=='w'||!!battle;$('undoMove').style.opacity=$('undoMove').disabled?'.45':'1'}
