function onSquare(x,y){if(battle||state.gameOver||state.turn!=='w')return;
const p=pieceAt(x,y);
if(selected&&legal.some(m=>m[0]===x&&m[1]===y)){state.undoSnapshot=JSON.stringify({...state,undoSnapshot:null});
const mover=selected,target=pieceAt(x,y);
selected=null;
legal=[];
if(target)startBattle(mover,target,x,y);
else applyMove(mover,x,y);
return}if(p&&p.color==='w'){selected=p;
legal=legalMoves(p)}else{selected=null;
legal=[]}renderBoard()}
function applyMove(p,x,y){const from=[p.x,p.y];
p.x=x;
p.y=y;
p.moved=true;
if(p.type==='P'&&(y===0||y===7)){p.type='Q';
p.maxHp=TYPES.Q.hp+5*(p.level-1);
p.hp=Math.min(p.maxHp,p.hp+8);
p.maxMp=TYPES.Q.mp+4*(p.level-1);
toast('¡Tu peón ha ascendido a Reina!');
addLog(`<strong>${label(p)}</strong> asciende por el tablero.`)}state.lastMove={from,to:[x,y]};
endTurn(p.color);
renderAll()}
function endTurn(movedColor){state.turn=movedColor==='w'?'b':'w';
if(movedColor==='b')state.move++;
selected=null;
legal=[];
const moves=allMoves(state.turn);
if(!moves.length){state.gameOver=true;
state.winner=inCheck(state.turn)?movedColor:null;
addLog(state.winner?`<strong>${state.winner==='w'?'Guardia del Alba':'La Sombra'}</strong> gana la partida por jaque mate.`:'La partida termina en tablas.');
toast(state.winner?(state.winner==='w'?'¡Jaque mate! Has ganado':'Jaque mate. La Sombra gana'):'Tablas.')}else if(inCheck(state.turn))addLog(`<strong>¡Jaque!</strong> El rey ${state.turn==='w'?'del Alba':'de la Sombra'} está amenazado.`);
save();
renderBoard();
renderHud();
if(state.turn==='b'&&!state.gameOver&&!battle)aiTimer=setTimeout(aiMove,650)}


