3: function pseudo(p){const out=[],{x,y,type,color}=p,dir=color==='w'?-1:1;const add=(a,b)=>{if(!inBounds(a,b))return false;const q=pieceAt(a,b);if(!q)out.push([a,b]);else if(q.color!==color)out.push([a,b]);return !q};if(type==='P'){if(inBounds(x,y+dir)&&!pieceAt(x,y+dir)){out.push([x,y+dir]);if(!p.moved&&!pieceAt(x,y+2*dir))out.push([x,y+2*dir])}for(const dx of [-1,1]){const q=pieceAt(x+dx,y+dir);if(q&&q.color!==color)out.push([x+dx,y+dir])}}else if(type==='N'){for(const[dx,dy]of [[1,2],[2,1],[2,-1],[1,-2],[-1,-2],[-2,-1],[-2,1],[-1,2]]){const q=pieceAt(x+dx,y+dy);if(inBounds(x+dx,y+dy)&&(!q||q.color!==color))out.push([x+dx,y+dy])}}else if(type==='K'){for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)if(dx||dy){const q=pieceAt(x+dx,y+dy);if(inBounds(x+dx,y+dy)&&(!q||q.color!==color))out.push([x+dx,y+dy])}}else{const dirs=[];if(type==='R'||type==='Q')dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(type==='B'||type==='Q')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dx,dy]of dirs){let a=x+dx,b=y+dy;while(add(a,b)){a+=dx;b+=dy}}}return out}function isAttacked(x,y,by){return state.pieces.some(p=>{if(!p.alive||p.color!==by)return false;if(p.type==='P')return Math.abs(p.x-x)===1&&p.y+(by==='w'?-1:1)===y;return pseudo(p).some(([a,b])=>a===x&&b===y)})}function king(color){return state.pieces.find(p=>p.alive&&p.color===color&&p.type==='K')}function inCheck(color){const k=king(color);return k?isAttacked(k.x,k.y,color==='w'?'b':'w'):true}function legalMoves(p){return pseudo(p).filter(([x,y])=>{const target=pieceAt(x,y);if(target?.type==='K')return false;const ox=p.x,oy=p.y;p.x=x;p.y=y;if(target)target.alive=false;const safe=!inCheck(p.color);p.x=ox;p.y=oy;if(target)target.alive=true;return safe})}function allMoves(color){return state.pieces.filter(p=>p.alive&&p.color===color).flatMap(p=>legalMoves(p).map(([x,y])=>({p,x,y,capture:!!pieceAt(x,y)})))}
4: function renderBoard(){boardEl.innerHTML='';const ranks=flipped?[...Array(8).keys()]:[...Array(8).keys()].reverse(),files=flipped?[...Array(8).keys()].reverse():[...Array(8).keys()];for(const y of ranks)for(const x of files){const sq=document.createElement('div');sq.className=`square ${(x+y)%2?'dark':'light'}`;sq.setAttribute('role','gridcell');sq.dataset.x=x;sq.dataset.y=y;const p=pieceAt(x,y);if(state.lastMove&&((state.lastMove.from[0]===x&&state.lastMove.from[1]===y)||(state.lastMove.to[0]===x&&state.lastMove.to[1]===y)))sq.classList.add('last-move');if(p?.type==='K'&&inCheck(p.color))sq.classList.add('check');if(selected===p)sq.classList.add('selected');if(legal.some(m=>m[0]===x&&m[1]===y))sq.classList.add('legal',p?'capture':'');if(p){const span=document.createElement('span');span.className=`piece ${p.color==='w'?'white':'black'}`;span.textContent=p.color==='w'?TYPES[p.type].glyph:TYPES[p.type].black;sq.append(span);if(own(p)&&p.level>1){const lev=document.createElement('span');lev.className='piece-level';lev.textContent=p.level;sq.append(lev)}}sq.onclick=()=>onSquare(x,y);boardEl.append(sq)}$('rankLabels').innerHTML=(flipped?'12345678':'87654321').split('').map(v=>`<span>${v}</span>`).join('');$('fileLabels').innerHTML=(flipped?'hgfedcba':'abcdefgh').split('').map(v=>`<span>${v}</span>`).join('')}
5: function onSquare(x,y){if(battle||state.gameOver||state.turn!=='w')return;const p=pieceAt(x,y);if(selected&&legal.some(m=>m[0]===x&&m[1]===y)){state.undoSnapshot=JSON.stringify({...state,undoSnapshot:null});const mover=selected,target=pieceAt(x,y);selected=null;legal=[];if(target)startBattle(mover,target,x,y);else applyMove(mover,x,y);return}if(p&&p.color==='w'){selected=p;legal=legalMoves(p)}else{selected=null;legal=[]}renderBoard()}function applyMove(p,x,y){const from=[p.x,p.y];p.x=x;p.y=y;p.moved=true;if(p.type==='P'&&(y===0||y===7)){p.type='Q';p.maxHp=TYPES.Q.hp+5*(p.level-1);p.hp=Math.min(p.maxHp,p.hp+8);p.maxMp=TYPES.Q.mp+4*(p.level-1);toast('¡Tu peón ha ascendido a Reina!');addLog(`<strong>${label(p)}</strong> asciende por el tablero.`)}state.lastMove={from,to:[x,y]};endTurn(p.color);renderAll()}function endTurn(movedColor){state.turn=movedColor==='w'?'b':'w';if(movedColor==='b')state.move++;selected=null;legal=[];const moves=allMoves(state.turn);if(!moves.length){state.gameOver=true;state.winner=inCheck(state.turn)?movedColor:null;addLog(state.winner?`<strong>${state.winner==='w'?'Guardia del Alba':'La Sombra'}</strong> gana la partida por jaque mate.`:'La partida termina en tablas.');toast(state.winner?(state.winner==='w'?'¡Jaque mate! Has ganado':'Jaque mate. La Sombra gana'):'Tablas.')}else if(inCheck(state.turn))addLog(`<strong>¡Jaque!</strong> El rey ${state.turn==='w'?'del Alba':'de la Sombra'} está amenazado.`);save();renderBoard();renderHud();if(state.turn==='b'&&!state.gameOver&&!battle)aiTimer=setTimeout(aiMove,650)}
