7: function startBattle(attacker,defender,x,y){
8:   clearTimeout(aiTimer);
9:   battle={attacker,defender,x,y,guard:{w:0,b:0},over:false,playerBusy:false};
10:   $('battleModal').classList.remove('hidden');
11:   $('battleTitle').textContent=`${label(attacker)} contra ${label(defender)}`;
12:   $('battleSubtitle').textContent=attacker.color==='w'?'Tu pieza desafía a una esencia rival.':'¡La Sombra ha iniciado un duelo!';
13:   $('battleMessage').textContent=attacker.color==='w'?'Elige una acción para comenzar.':'La Sombra prepara su ataque…';
14:   updateBattle();
15:   renderHud();
16:   if(attacker.color==='b')setTimeout(enemyBattleTurn,650);
17: }
18: function battlePiece(color){return battle&&(battle.attacker.color===color?battle.attacker:battle.defender)}
19: function battleGlyph(piece){return piece.color==='w'?TYPES[piece.type].glyph:TYPES[piece.type].black}
20: function updateBattle(){
21:   if(!battle)return;
22:   for(const [piece,prefix] of [[battle.attacker,'attacker'],[battle.defender,'defender']]){
23:     const type=TYPES[piece.type];
24:     $(`${prefix}Glyph`).textContent=battleGlyph(piece);
25:     $(`${prefix}Name`).textContent=label(piece);
26:     $(`${prefix}Meta`).textContent=`Nv. ${piece.level} · ${piece.color==='w'?'Guardia del Alba':'La Sombra'}`;
27:     $(`${prefix}HpBar`).style.width=`${Math.max(0,piece.hp)/piece.maxHp*100}%`;
28:     $(`${prefix}HpText`).textContent=`${Math.max(0,piece.hp)} / ${piece.maxHp} PV`;
29:     $(`${prefix}MpBar`).style.width=`${Math.max(0,piece.mp)/piece.maxMp*100}%`;
30:     $(`${prefix}MpText`).textContent=`${Math.max(0,piece.mp)} / ${piece.maxMp} ÉTER`;
31:     $(`${prefix}Card`).classList.toggle('active-combatant',piece.color==='w');
32:   }
33:   $('battleTurn').textContent=battle.over?'DUELO RESUELTO':battlePiece('w')?.color==='w'?'TU ACCIÓN':'TURNO RIVAL';
34:   if(battle.over)return;
35:   const actions=$('battleActions');
36:   actions.innerHTML='';
37:   const hero=battlePiece('w'),canAct=hero&&hero.hp>0&&!battle.playerBusy;
38:   const addAction=(title,desc,fn,disabled=false,cls='')=>{
39:     const button=document.createElement('button');button.className=`battle-action ${cls}`;button.disabled=disabled;
40:     button.innerHTML=`<strong>${title}</strong><small>${desc}</small>`;button.onclick=fn;actions.append(button);
41:   };
42:   addAction('⚔ Atacar',`Daño ${Math.max(2,Math.round(TYPES[hero.type].atk*(1+hero.level*.08)))} PV`,()=>playerBattleAction('attack'),!canAct);
43:   const cost=hero.type==='B'?5:hero.type==='K'||hero.type==='R'?6:8;
44:   addAction(`✧ ${TYPES[hero.type].ability}`,`${TYPES[hero.type].skill} · ${cost} éter`,()=>playerBattleAction('skill'),!canAct||hero.mp<cost,'special');
45:   addAction('◈ Defender','Reduce el próximo golpe y recupera 2 éter',()=>playerBattleAction('guard'),!canAct,'special');
46:   addAction(`⚗ Poción ×${state.inventory.potion}`,'+18 PV · objeto de un uso',()=>playerBattleAction('potion'),!canAct||!state.inventory.potion||hero.hp>=hero.maxHp,'item-action');
47: }
48: function battleDamage(source,target,multiplier=1){
49:   const base=TYPES[source.type].atk+Math.floor(source.level*1.4);
50:   const critical=Math.random()<(.08+(source.type==='N'?.18:0));
51:   const raw=Math.max(2,Math.round(base*multiplier*(critical?1.7:1)));
52:   const blocked=battle.guard[target.color]||0;
53:   battle.guard[target.color]=0;
54:   const damage=Math.max(1,raw-blocked);
55:   target.hp=Math.max(0,target.hp-damage);
56:   return `${label(source)} inflige ${damage} PV${critical?' (¡crítico!)':''}${blocked?`; la guardia absorbe ${Math.min(raw,blocked)}.`:'.'}`;
57: }
58: function playerBattleAction(action){
59:   if(!battle||battle.over||battle.playerBusy)return;
60:   const hero=battlePiece('w'),foe=battlePiece('b');
61:   if(!hero||hero.hp<=0)return;
62:   let message='';
63:   if(action==='attack')message=battleDamage(hero,foe);
64:   else if(action==='guard'){battle.guard.w=8;hero.mp=Math.min(hero.maxMp,hero.mp+2);message=`${label(hero)} adopta una guardia firme y recupera 2 de éter.`}
65:   else if(action==='potion'){
66:     if(!state.inventory.potion||hero.hp>=hero.maxHp)return;
67:     state.inventory.potion--;const restored=Math.min(18,hero.maxHp-hero.hp);hero.hp+=restored;message=`La Poción restaura ${restored} PV a ${label(hero)}.`;
68:   }else if(action==='skill')message=useBattleSkill(hero,foe);
69:   $('battleMessage').textContent=message;
70:   if(foe.hp<=0){updateBattle();finishBattle(hero);return}
71:   battle.playerBusy=true;updateBattle();
72:   setTimeout(()=>{if(!battle||battle.over)return;enemyBattleTurn()},700);
73: }
74: function useBattleSkill(user,target){
75:   const cost=user.type==='B'?5:user.type==='K'||user.type==='R'?6:8;
76:   if(user.mp<cost)return 'No hay suficiente éter.';
77:   user.mp-=cost;
78:   if(user.type==='K'){
79:     const damage=battleDamage(user,target,1.15);const healed=Math.min(8,user.maxHp-user.hp);user.hp+=healed;return `${damage} Mandato real restaura ${healed} PV.`;
80:   }
81:   if(user.type==='R'){
82:     const healed=Math.min(10,user.maxHp-user.hp);user.hp+=healed;battle.guard[user.color]=9;return `Bastión restaura ${healed} PV y absorbe hasta 9 de daño.`;
83:   }
84:   if(user.type==='B'){
85:     const healed=Math.min(12,user.maxHp-user.hp);user.hp+=healed;user.mp=Math.min(user.maxMp,user.mp+3);return `Luz sanadora restaura ${healed} PV y 3 de éter.`;
86:   }
87:   if(user.type==='N')return battleDamage(user,target,1.65);
88:   if(user.type==='P')return battleDamage(user,target,1.25+Math.min(user.level,5)*.08);
89:   return battleDamage(user,target,1.8);
90: }
91: function enemyBattleTurn(){
92:   if(!battle||battle.over)return;
93:   const enemy=battlePiece('b'),hero=battlePiece('w');
94:   if(!enemy||enemy.hp<=0){finishBattle(hero);return}
95:   battle.playerBusy=false;
96:   let message;
97:   const hurt=enemy.hp<enemy.maxHp*.45,canHeal=enemy.type==='B'||enemy.type==='K'||enemy.type==='R';
98:   if(hurt&&canHeal&&enemy.mp>=5&&Math.random()<.48)message=useBattleSkill(enemy,hero);
99:   else if(enemy.mp>=8&&Math.random()<.28)message=useBattleSkill(enemy,hero);
100:   else if(Math.random()<.16){battle.guard.b=7;enemy.mp=Math.min(enemy.maxMp,enemy.mp+2);message=`La Sombra protege a ${label(enemy)}.`}
101:   else message=battleDamage(enemy,hero);
102:   $('battleMessage').textContent=message;
103:   updateBattle();
104:   if(hero.hp<=0)finishBattle(enemy);
105:   else {battle.playerBusy=false;updateBattle()}
106: }
107: function finishBattle(winner){
108:   if(!battle||battle.over)return;
109:   battle.over=true;
110:   const {attacker,defender,x,y}=battle,attackerWon=winner===attacker;
111:   const loser=attackerWon?defender:attacker;
112:   loser.alive=false;loser.hp=0;
113:   if(attackerWon){attacker.x=x;attacker.y=y;attacker.moved=true}
114:   const winnerColor=winner.color;
115:   if(winnerColor==='w'){
116:     const gained=30+TYPES[loser.type].cost*4;state.gold+=gained;
117:     winner.xp+=35+TYPES[loser.type].cost*3;
118:     let levelMessage='';
119:     while(winner.xp>=winner.level*50){winner.xp-=winner.level*50;winner.level++;winner.maxHp+=5;winner.hp=Math.min(winner.maxHp,winner.hp+5);winner.maxMp+=3;winner.mp=Math.min(winner.maxMp,winner.mp+3);levelMessage=` ¡${label(winner)} alcanza el nivel ${winner.level}!`}
120:     state.inventory.potion=(state.inventory.potion||0)+1;
121:     $('battleResult').innerHTML=`¡Victoria! ${label(winner)} gana ${gained} de oro, una Poción y experiencia.${levelMessage}<button id="battleContinue">Continuar</button>`;
122:     addLog(`<strong>${label(winner)}</strong> vence el duelo y obtiene ${gained} de oro.`);
123:   }else{
124:     const gained=15;state.gold+=gained;winner.xp+=15;
125:     $('battleResult').innerHTML=`Derrota. ${label(winner)} resiste y recibe ${gained} de oro por su valor.<button id="battleContinue">Continuar</button>`;
126:     addLog(`<strong>${label(winner)}</strong> sobrevive al duelo, pero el ejército pierde ${label(loser)}.`);
127:   }
128:   $('battleActions').innerHTML='';$('battleResult').classList.remove('hidden');$('battleContinue').onclick=closeBattle;
129:   $('battleMessage').textContent=attackerWon?`${label(attacker)} prevalece en el duelo.`:`${label(defender)} resiste y cambia el rumbo del combate.`;
130:   updateBattle();
131:   renderHud();save();
132: }
133: function closeBattle(){
134:   if(!battle||!battle.over)return;
135:   const movedColor=battle.attacker.color;
136:   $('battleModal').classList.add('hidden');$('battleResult').classList.add('hidden');
137:   $('battleActions').innerHTML='';battle=null;selected=null;legal=[];
138:   endTurn(movedColor);renderAll();
139: }
